def cZeroBlockCompression (P : C₀(Γ, X) →L[𝕜] C₀(Γ, X)) (A : Set Γ) :
    cZeroSupportedSubmodule (𝕜 := 𝕜) (X := X) A →L[𝕜] cZeroSupportedSubmodule (𝕜 := 𝕜) (X := X) A :=
  (cZeroProjectionTo A).comp (P.comp (cZeroSupportedSubmodule A).subtypeL)

